insert into nave_exercises (id,phase_id,axis,name,intro,minimum,duration_min,source,condition,homework,repeatable_per,tier,sessao,porque,blocos,min_bloco,tempo_fonte,ficha) values ('V2','F3','V','As 5 Perguntas da Promessa','ATENÇÃO — divergência de fonte. Este exercício está no PDF da aula 09 mas não é falado no vídeo; no vídeo o primeiro exercício é o 3+1 do Brand Gap (V1). Use como complemento, não como substituto. Se você não responde claramente a cada uma, há problema no posicionamento.',false,25,'M05 A09 (só no PDF — não aparece na transcrição da aula)',null,false,null,'extra','workshop','Divergência de fonte: está no PDF, não na aula. Use como complemento do V1, nunca no lugar dele.',5,5,'padrão do método: 5 min por bloco',false) on conflict (id) do update set phase_id=excluded.phase_id, axis=excluded.axis, name=excluded.name, intro=excluded.intro, minimum=excluded.minimum, duration_min=excluded.duration_min, source=excluded.source, condition=excluded.condition, homework=excluded.homework, repeatable_per=excluded.repeatable_per, tier=excluded.tier, sessao=excluded.sessao, porque=excluded.porque, blocos=excluded.blocos, min_bloco=excluded.min_bloco, tempo_fonte=excluded.tempo_fonte, ficha=excluded.ficha;
