insert into nave_exercises (id,phase_id,axis,name,intro,minimum,duration_min,source,condition,homework,repeatable_per,tier,sessao,porque,blocos,min_bloco,tempo_fonte,ficha) values ('V3','F3','V','Diagrama de Percepção: Passado, Presente e Futuro','Só se aplica a marca que já existe — marca nova pula direto para o V4. Os donos sabem muito bem o passado: "ano passado a gente estava bem". Se o passado foi diferente do presente, já nasce uma conversa dentro da equipe sobre por que isso aconteceu.',false,20,'M05 A09','marca_existente',false,null,'sinal','workshop','Só marca existente. A percepção caiu e ninguém sabe explicar quando.',4,5,'padrão do método: 5 min por bloco',false) on conflict (id) do update set phase_id=excluded.phase_id, axis=excluded.axis, name=excluded.name, intro=excluded.intro, minimum=excluded.minimum, duration_min=excluded.duration_min, source=excluded.source, condition=excluded.condition, homework=excluded.homework, repeatable_per=excluded.repeatable_per, tier=excluded.tier, sessao=excluded.sessao, porque=excluded.porque, blocos=excluded.blocos, min_bloco=excluded.min_bloco, tempo_fonte=excluded.tempo_fonte, ficha=excluded.ficha;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V3',0,'passado','Como a marca era percebida no passado?','longtext',null,'{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V3',1,'presente','Qual é a percepção hoje?','longtext','Provavelmente uma percepção que eles não gostariam de ter — é para isso que te contrataram.','{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V3',2,'futuro','Como gostariam de ser percebidos?','longtext','Aqui tem muito ouro.','{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V3',3,'porque','Por que chegou até aqui?','longtext','Houve planejamento? Se houve, por que não foi feito? Passado e presente revelam a responsabilidade da própria empresa.','{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercises (id,phase_id,axis,name,intro,minimum,duration_min,source,condition,homework,repeatable_per,tier,sessao,porque,blocos,min_bloco,tempo_fonte,ficha) values ('V4','F3','V','Percepção: Categoria, Comunidade e Impacto','Complementa o V3, ou substitui se a marca for nova. Exercício de post-it — deixe as pessoas responderem. Se acharem redundante, diga na cara: "a gente investiga o mesmo lugar por ângulos diferentes para ter certeza".',false,15,'M05 A09 (transcrição — o PDF troca o 3º bloco por ''Promessa'')',null,false,null,'sinal','workshop','Não está claro o que a marca faz e, principalmente, o que ela NÃO faz.',3,5,'padrão do método: 5 min por bloco',false) on conflict (id) do update set phase_id=excluded.phase_id, axis=excluded.axis, name=excluded.name, intro=excluded.intro, minimum=excluded.minimum, duration_min=excluded.duration_min, source=excluded.source, condition=excluded.condition, homework=excluded.homework, repeatable_per=excluded.repeatable_per, tier=excluded.tier, sessao=excluded.sessao, porque=excluded.porque, blocos=excluded.blocos, min_bloco=excluded.min_bloco, tempo_fonte=excluded.tempo_fonte, ficha=excluded.ficha;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V4',0,'faz','Categoria — o que a marca faz?','longtext',null,'{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V4',1,'nao_faz','Categoria — o que a marca NÃO faz?','longtext','A negativa costuma ser mais importante que a positiva.','{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V4',2,'comunidade','Comunidade — quem faz parte?','longtext','Não vale ''todo mundo''. Se é a galera da maromba, qual maromba? As comunidades já existem; você é adotado por ela.','{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V4',3,'nao_comunidade','Comunidade — quem NÃO faz parte?','longtext','O inimigo e o descrente do Branding Primitivo. É a linha que define: daqui pra lá não é nós.','{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V4',4,'impacto_hoje','Impacto — como as pessoas se sentem ao interagir com a gente hoje?','longtext','Interagir é qualquer coisa: ver o conteúdo, ver o logo, entrar na loja, entrar no Instagram.','{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V4',5,'impacto_futuro','Impacto — como elas deveriam se sentir?','longtext',null,'{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercises (id,phase_id,axis,name,intro,minimum,duration_min,source,condition,homework,repeatable_per,tier,sessao,porque,blocos,min_bloco,tempo_fonte,ficha) values ('V5','F3','V','Fatos, Obstáculos e Oportunidades (marca)','Quase uma SWOT, mas mais prático. 5 minutos por bloco: é o que o cliente já sabe, sem estudar, sem olhar o chat. Obstáculo não precisa derivar do fato — é provável que ele lembre de coisa nova aqui.',false,15,'M05 A09',null,false,null,'sinal','workshop','Faltam fatos: o cliente fala por impressão.',3,5,'M05 A09 · "você coloca cinco minutos, não precisa pensar muito"',false) on conflict (id) do update set phase_id=excluded.phase_id, axis=excluded.axis, name=excluded.name, intro=excluded.intro, minimum=excluded.minimum, duration_min=excluded.duration_min, source=excluded.source, condition=excluded.condition, homework=excluded.homework, repeatable_per=excluded.repeatable_per, tier=excluded.tier, sessao=excluded.sessao, porque=excluded.porque, blocos=excluded.blocos, min_bloco=excluded.min_bloco, tempo_fonte=excluded.tempo_fonte, ficha=excluded.ficha;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V5',0,'fatos','Fatos sobre a nossa marca e o nosso mercado','list',null,'{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V5',1,'obstaculos','Obstáculos e desafios de hoje','list','Quando ele começar a falar algo promissor, afunde: ''peraí, o que você quer dizer com isso?''','{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V5',2,'oportunidades','Oportunidades que dá para aproveitar','list',null,'{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercises (id,phase_id,axis,name,intro,minimum,duration_min,source,condition,homework,repeatable_per,tier,sessao,porque,blocos,min_bloco,tempo_fonte,ficha) values ('V6','F3','V','Problemas e Conflitos','Expõe as tensões verdadeiras. Cada bloco fecha com ''e como a nossa marca resolve isso?''. Os conflitos externos e internos aqui são do PÚBLICO, não da empresa.',false,30,'M05 A09',null,false,null,'sinal','workshop','Discurso ≠ prática. O bloco de conflitos filosóficos existe para expor isso.',6,5,'padrão do método: 5 min por bloco',false) on conflict (id) do update set phase_id=excluded.phase_id, axis=excluded.axis, name=excluded.name, intro=excluded.intro, minimum=excluded.minimum, duration_min=excluded.duration_min, source=excluded.source, condition=excluded.condition, homework=excluded.homework, repeatable_per=excluded.repeatable_per, tier=excluded.tier, sessao=excluded.sessao, porque=excluded.porque, blocos=excluded.blocos, min_bloco=excluded.min_bloco, tempo_fonte=excluded.tempo_fonte, ficha=excluded.ficha;
