insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V6',1,'externos_resolve','Como a nossa marca resolve esses problemas?','longtext',null,'{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V6',2,'internos','Conflitos internos — como esses problemas fazem o cliente se sentir?','longtext','Quais mais se repetem e quais se destacam pela intensidade — os que tiram o sono, que ele paga caro para resolver.','{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V6',3,'internos_resolve','Como a nossa marca resolve ou minimiza essas frustrações?','longtext',null,'{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V6',4,'filosoficos','Conflitos filosóficos — qual é o problema mais profundo?','longtext','Existe um conflito maior e mais abrangente com o qual a marca contribui ou luta contra? Ex. Marcados: fazer o designer ser valorizado e não marginalizado.','{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V6',5,'filosoficos_resolve','Como a marca contribui com esse desafio?','longtext',null,'{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercises (id,phase_id,axis,name,intro,minimum,duration_min,source,condition,homework,repeatable_per,tier,sessao,porque,blocos,min_bloco,tempo_fonte,ficha) values ('V7','F3','V','Radar dos Principais Players','Desenhe um alvo. O logo do cliente no centro. Ele cola os concorrentes em post-it: quanto mais perto do centro, mais parecida a proposta — ou mais clientes eles estão tirando dele. Os de fora têm proposta similar mas não são considerados concorrentes diretos. É a partir daqui que o workshop para de olhar para dentro e começa a olhar para os outros.',false,5,'M05 A09 (transcrição — ausente do PDF)',null,false,null,'sinal','workshop','Concorrência mal mapeada ou negada.',1,5,'padrão do método: 5 min por bloco',false) on conflict (id) do update set phase_id=excluded.phase_id, axis=excluded.axis, name=excluded.name, intro=excluded.intro, minimum=excluded.minimum, duration_min=excluded.duration_min, source=excluded.source, condition=excluded.condition, homework=excluded.homework, repeatable_per=excluded.repeatable_per, tier=excluded.tier, sessao=excluded.sessao, porque=excluded.porque, blocos=excluded.blocos, min_bloco=excluded.min_bloco, tempo_fonte=excluded.tempo_fonte, ficha=excluded.ficha;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V7',0,'quadro','Quadro','draw','O radar: alvo com o cliente no centro, concorrentes por proximidade','{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V7',1,'radar','Players por proximidade','table',null,'{"columns": ["Player", "Anel (1 = mais próximo · 3 = periferia)", "Por que está nesse anel"], "repeatable": true, "min_rows": 3}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercises (id,phase_id,axis,name,intro,minimum,duration_min,source,condition,homework,repeatable_per,tier,sessao,porque,blocos,min_bloco,tempo_fonte,ficha) values ('V8','F3','V','Fã e Hater — a marca e os concorrentes','"Branding é o que dizem sobre você quando você não está na sala" — virou exercício. Duas rodadas: primeiro sobre a MARCA DO CLIENTE, depois sobre cada concorrente. Vale para marca que ainda não existe: imagine o que um fã diria. 5 minutos no relógio por rodada.',true,15,'M05 A09 (transcrição — o PDF omite a rodada sobre a própria marca)',null,false,null,'espinha','workshop','Listado no próprio material como um dos três a fazer quando o tempo é curto. Devolve o diferencial percebido.',3,5,'M05 A09 · "bota cinco minutos no relógio"',false) on conflict (id) do update set phase_id=excluded.phase_id, axis=excluded.axis, name=excluded.name, intro=excluded.intro, minimum=excluded.minimum, duration_min=excluded.duration_min, source=excluded.source, condition=excluded.condition, homework=excluded.homework, repeatable_per=excluded.repeatable_per, tier=excluded.tier, sessao=excluded.sessao, porque=excluded.porque, blocos=excluded.blocos, min_bloco=excluded.min_bloco, tempo_fonte=excluded.tempo_fonte, ficha=excluded.ficha;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V8',0,'propria_fa','O que um FÃ diria da nossa marca se a gente não estivesse na sala?','longtext',null,'{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V8',1,'propria_hater','O que um HATER diria da nossa marca se a gente não estivesse na sala?','longtext',null,'{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V8',2,'matriz','Por concorrente','table',null,'{"columns": ["Concorrente", "O que um FÃ diria", "O que um HATER diria"], "repeatable": true, "min_rows": 3, "max_rows": 5}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
