insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V9',2,'desejado','Onde eles gostariam de estar?','longtext',null,'{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercises (id,phase_id,axis,name,intro,minimum,duration_min,source,condition,homework,repeatable_per,tier,sessao,porque,blocos,min_bloco,tempo_fonte,ficha) values ('V10','F3','V','Jobs to be Done','Serve para descobrir concorrentes que o cliente não sabia que tinha. Em vez de partir das empresas, parte das dores. Faz você pesquisar coisas que não pesquisaria. Use quando houver dificuldade em definir os players. Ex.: o TikTok Shop virou concorrente de plataforma de e-commerce — e já era falado havia anos.',false,25,'M05 A09',null,false,null,'sinal','workshop','Dificuldade de definir quem são os players de verdade.',5,5,'padrão do método: 5 min por bloco',false) on conflict (id) do update set phase_id=excluded.phase_id, axis=excluded.axis, name=excluded.name, intro=excluded.intro, minimum=excluded.minimum, duration_min=excluded.duration_min, source=excluded.source, condition=excluded.condition, homework=excluded.homework, repeatable_per=excluded.repeatable_per, tier=excluded.tier, sessao=excluded.sessao, porque=excluded.porque, blocos=excluded.blocos, min_bloco=excluded.min_bloco, tempo_fonte=excluded.tempo_fonte, ficha=excluded.ficha;
