insert into nave_exercises (id,phase_id,axis,name,intro,minimum,duration_min,source,condition,homework,repeatable_per,tier,sessao,porque,blocos,min_bloco,tempo_fonte,ficha) values ('V12','F3','V','Escada da Marca','Sobe do mais fácil ao mais difícil, e cada degrau se constrói a partir do anterior — sempre volte à resposta de baixo. Exemplo Dove: 1/4 de creme hidratante → pele macia e confortável ao toque → sinto minha beleza valorizada → mereço ter minha autoestima elevada. Um sabonete conectado ao sistema de crenças mais íntimo da consumidora. Faça com post-it e escracho; a poesia vem depois, com a equipe.',false,20,'M05 A09 parte 2 (transcrição — ausente do PDF)',null,false,null,'sinal','workshop','O produto não conecta com nada maior — falta a ponte do atributo até o propósito.',4,5,'padrão do método: 5 min por bloco',false) on conflict (id) do update set phase_id=excluded.phase_id, axis=excluded.axis, name=excluded.name, intro=excluded.intro, minimum=excluded.minimum, duration_min=excluded.duration_min, source=excluded.source, condition=excluded.condition, homework=excluded.homework, repeatable_per=excluded.repeatable_per, tier=excluded.tier, sessao=excluded.sessao, porque=excluded.porque, blocos=excluded.blocos, min_bloco=excluded.min_bloco, tempo_fonte=excluded.tempo_fonte, ficha=excluded.ficha;
