insert into nave_exercises (id,phase_id,axis,name,intro,minimum,duration_min,source,condition,homework,repeatable_per,tier,sessao,porque,blocos,min_bloco,tempo_fonte,ficha) values ('V13','F3','V','Diferenciais Estratégicos','Quatro partes em sequência. As duas últimas só funcionam bem porque vêm depois de todo o resto — se você perguntasse no começo, as respostas viriam horríveis.',false,25,'M05 A09 parte 2 (transcrição — ausente do PDF)',null,false,null,'espinha','workshop','Entrega diferencial único, lembrança e mensagem central: blocos 5 e 6 do relatório, praticamente prontos.',5,5,'padrão do método: 5 min por bloco',false) on conflict (id) do update set phase_id=excluded.phase_id, axis=excluded.axis, name=excluded.name, intro=excluded.intro, minimum=excluded.minimum, duration_min=excluded.duration_min, source=excluded.source, condition=excluded.condition, homework=excluded.homework, repeatable_per=excluded.repeatable_per, tier=excluded.tier, sessao=excluded.sessao, porque=excluded.porque, blocos=excluded.blocos, min_bloco=excluded.min_bloco, tempo_fonte=excluded.tempo_fonte, ficha=excluded.ficha;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V13',0,'players','1. Opções similares e o diferencial estratégico de cada uma','table','Use os players do radar (V7) mais os que apareceram no Jobs to be Done (V10).','{"columns": ["Player", "Diferencial estratégico dele"], "repeatable": true, "min_rows": 3}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V13',1,'preferencia','2. Preferência — por que nossos clientes deixariam cada um deles para comprar da gente?','table','Não dá para ganhar sempre. Marcar ''não viriam'' já economiza esforço de mercado.','{"columns": ["Player", "Por que sairiam dele para vir para nós", "(ou) Por que NÃO viriam"], "repeatable": true}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
