insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V13',3,'lembranca','4. Qual lembrança queremos deixar na mente dos consumidores?','longtext','Se travar: ''pensa na Nike; qual é a marca que você mais gosta e que lembrança ela deixou em você?''','{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
