insert into nave_exercises (id,phase_id,axis,name,intro,minimum,duration_min,source,condition,homework,repeatable_per,tier,sessao,porque,blocos,min_bloco,tempo_fonte,ficha) values ('V14','F5','V','Auditoria da Concorrência (verbal, presença e visual)','ÚNICO exercício do bloco que NÃO é feito com o cliente — é feito por você e sua equipe depois do workshop. Entre no site, nas mídias sociais, nos grupos de WhatsApp, e tente comprar um produto para ver como tratam na venda. Objetivo: mapear as palavras, mensagens e territórios visuais já ocupados, para achar o espaço vazio.',true,300,'M05 A09 parte 2 (transcrição — ausente do PDF)',null,false,null,'espinha','solo','Sem a auditoria você não sabe qual espaço de posicionamento está livre. Feita por você, depois.',5,60,'inferência: auditoria é trabalho seu, fora da sessão',false) on conflict (id) do update set phase_id=excluded.phase_id, axis=excluded.axis, name=excluded.name, intro=excluded.intro, minimum=excluded.minimum, duration_min=excluded.duration_min, source=excluded.source, condition=excluded.condition, homework=excluded.homework, repeatable_per=excluded.repeatable_per, tier=excluded.tier, sessao=excluded.sessao, porque=excluded.porque, blocos=excluded.blocos, min_bloco=excluded.min_bloco, tempo_fonte=excluded.tempo_fonte, ficha=excluded.ficha;
