insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('V14',1,'verbal','Auditoria verbal — frases do site, bio do Instagram e do LinkedIn, embalagem','table','Ex. Shopify: ''abra uma loja virtual, não importa o nicho'' → customização, democrático, acessível.','{"columns": ["Player", "Frase capturada", "Atributos que ela puxa"], "repeatable": true}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
