insert into nave_exercises (id,phase_id,axis,name,intro,minimum,duration_min,source,condition,homework,repeatable_per,tier,sessao,porque,blocos,min_bloco,tempo_fonte,ficha) values ('E1','F3','E','História de Criação','Pode ir como lição de casa ANTES da imersão — é assim que Lona costuma passar. Alguns fundadores voltam com seis páginas escritas sozinhos; outros só produzem se você extrair em conversa. Teste as duas formas. O que importa é chegar na origem, nos valores, na fagulha do começo.',true,0,'M05 A11',null,true,null,'espinha','casa','Alimenta propósito, valores e narrativa — e vai como lição de casa, então não custa tempo de sala.',3,0,'lição de casa — não consome tempo de sala',false) on conflict (id) do update set phase_id=excluded.phase_id, axis=excluded.axis, name=excluded.name, intro=excluded.intro, minimum=excluded.minimum, duration_min=excluded.duration_min, source=excluded.source, condition=excluded.condition, homework=excluded.homework, repeatable_per=excluded.repeatable_per, tier=excluded.tier, sessao=excluded.sessao, porque=excluded.porque, blocos=excluded.blocos, min_bloco=excluded.min_bloco, tempo_fonte=excluded.tempo_fonte, ficha=excluded.ficha;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('E1',0,'passado','Passado','longtext','A história do fundador antes da empresa.','{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('E1',1,'inflexao','Ponto de inflexão','longtext','A fagulha. O momento que gerou a ideia do negócio.','{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
