insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('E2',3,'importou','Por que ela importou?','longtext',null,'{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercises (id,phase_id,axis,name,intro,minimum,duration_min,source,condition,homework,repeatable_per,tier,sessao,porque,blocos,min_bloco,tempo_fonte,ficha) values ('E3','F3','E','Pontos de Virada, Lições e Identidade','Rodada dinâmica de post-it que vem LOGO DEPOIS da História de Criação (E1) — o fundador olha o próprio texto e fica muito mais fácil responder. Três degraus encadeados. Se alguém questionar que isso é sobre o dono e não sobre a marca: "não existe marca, existem as pessoas que constroem a empresa; a marca é o resultado, é a reputação".',false,15,'M05 A11 (transcrição — ausente do PDF)',null,false,null,'sinal','workshop','A história de criação voltou rasa. Este destrava.',3,5,'padrão do método: 5 min por bloco',false) on conflict (id) do update set phase_id=excluded.phase_id, axis=excluded.axis, name=excluded.name, intro=excluded.intro, minimum=excluded.minimum, duration_min=excluded.duration_min, source=excluded.source, condition=excluded.condition, homework=excluded.homework, repeatable_per=excluded.repeatable_per, tier=excluded.tier, sessao=excluded.sessao, porque=excluded.porque, blocos=excluded.blocos, min_bloco=excluded.min_bloco, tempo_fonte=excluded.tempo_fonte, ficha=excluded.ficha;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('E3',0,'viradas','1. Liste os momentos em que você pensou: “a minha vida mudou aqui”','list',null,'{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('E3',1,'licoes','2. O que você aprendeu com cada ponto de virada?','longtext','Que lição ele te trouxe.','{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('E3',2,'identidade','3. Como essas lições refletiram na sua identidade?','longtext','Como mudaram o seu jeito de fazer as coisas, de tomar decisões e de agir.','{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercises (id,phase_id,axis,name,intro,minimum,duration_min,source,condition,homework,repeatable_per,tier,sessao,porque,blocos,min_bloco,tempo_fonte,ficha) values ('E4','F3','E','Sistema de Crenças: Defendemos / Somos contra','Primeira parte do bloco de crenças, antes de Visão e Missões. Para saber no que a marca acredita costuma ser mais fácil começar pelo que ela NÃO acredita — a negativa puxa a resposta para aquilo que a pessoa realmente se importa. Não é posição política pessoal: é a realidade da empresa e da marca. Formato dinâmico, todo mundo refletindo junto.',false,20,'M05 A11 (transcrição — ausente do PDF)',null,false,null,'sinal','workshop','Valores genéricos: honestidade, transparência, qualidade. A negativa quebra isso.',4,5,'padrão do método: 5 min por bloco',false) on conflict (id) do update set phase_id=excluded.phase_id, axis=excluded.axis, name=excluded.name, intro=excluded.intro, minimum=excluded.minimum, duration_min=excluded.duration_min, source=excluded.source, condition=excluded.condition, homework=excluded.homework, repeatable_per=excluded.repeatable_per, tier=excluded.tier, sessao=excluded.sessao, porque=excluded.porque, blocos=excluded.blocos, min_bloco=excluded.min_bloco, tempo_fonte=excluded.tempo_fonte, ficha=excluded.ficha;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('E4',0,'defendemos','Defendemos…','list',null,'{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('E4',1,'contra','Somos contra…','list',null,'{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('E4',2,'acreditamos','Acreditamos…','list',null,'{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
