insert into nave_exercises (id,phase_id,axis,name,intro,minimum,duration_min,source,condition,homework,repeatable_per,tier,sessao,porque,blocos,min_bloco,tempo_fonte,ficha) values ('E5','F3','E','Visão de Mundo e Missões','Segunda parte do bloco de crenças — a razão de existência. NÃO explique a pirâmide para o cliente: você se enrola, ele fica confuso e trava. Faça as perguntas e organize depois. Depois é discussão · post-it · discussão · post-it.',true,10,'M05 A11',null,false,null,'espinha','workshop','Visão e missões — sem isso a plataforma não fecha e o propósito fica solto.',2,5,'padrão do método: 5 min por bloco',false) on conflict (id) do update set phase_id=excluded.phase_id, axis=excluded.axis, name=excluded.name, intro=excluded.intro, minimum=excluded.minimum, duration_min=excluded.duration_min, source=excluded.source, condition=excluded.condition, homework=excluded.homework, repeatable_per=excluded.repeatable_per, tier=excluded.tier, sessao=excluded.sessao, porque=excluded.porque, blocos=excluded.blocos, min_bloco=excluded.min_bloco, tempo_fonte=excluded.tempo_fonte, ficha=excluded.ficha;
