insert into nave_exercises (id,phase_id,axis,name,intro,minimum,duration_min,source,condition,homework,repeatable_per,tier,sessao,porque,blocos,min_bloco,tempo_fonte,ficha) values ('E7','F3','E','Propósito — Ikigai adaptado (com negativos)','Existe para fugir do caráter abstrato do propósito — "não é salvar as baleias e a mata atlântica". Quatro áreas de observação, e CADA UMA tem um lado positivo e um negativo. Depois: agrupar os post-its em quatro colunas, escrever UM PARÁGRAFO por bloco, e só então gerar as declarações (com IA, a partir dos quatro textos). O propósito está na interseção — a zona azul do Ikigai.',true,35,'M05 A11 (transcrição — o PDF omite os negativos e a etapa dos 4 parágrafos)',null,false,null,'espinha','workshop','Propósito é o elemento 1 da plataforma. Nenhum outro instrumento produz.',7,5,'padrão do método: 5 min por bloco',false) on conflict (id) do update set phase_id=excluded.phase_id, axis=excluded.axis, name=excluded.name, intro=excluded.intro, minimum=excluded.minimum, duration_min=excluded.duration_min, source=excluded.source, condition=excluded.condition, homework=excluded.homework, repeatable_per=excluded.repeatable_per, tier=excluded.tier, sessao=excluded.sessao, porque=excluded.porque, blocos=excluded.blocos, min_bloco=excluded.min_bloco, tempo_fonte=excluded.tempo_fonte, ficha=excluded.ficha;
