insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('E7',12,'declaracao','Declaração de propósito','text','Existimos para [ação] + [para quem] + [gerando que transformação]. Gere várias e deixe o cliente escolher.','{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercises (id,phase_id,axis,name,intro,minimum,duration_min,source,condition,homework,repeatable_per,tier,sessao,porque,blocos,min_bloco,tempo_fonte,ficha) values ('E8','F3','E','Atributos de Personalidade','A identidade visual E a verbal partem daqui. Tenha uma biblioteca de atributos pronta — baralho de mercado ou lista gerada por IA funciona igual. Cuidado com baralhos em que cada carta é um universo inteiro: cinco cartas viram cinco universos e você trava na hora de criar. Leve exemplos de marca por atributo (animada: Porsche, Absolut, Red Bull · competência: Amex, IBM, Toyota — e mostre como ''confiável'' se quebra em cuidadoso, sóbrio, trabalhador). A mecânica é simples: a gente é / a gente não é.',true,20,'M05 A11',null,false,null,'espinha','workshop','A identidade visual E a verbal partem daqui. É o gargalo do módulo 7 inteiro.',4,5,'padrão do método: 5 min por bloco',false) on conflict (id) do update set phase_id=excluded.phase_id, axis=excluded.axis, name=excluded.name, intro=excluded.intro, minimum=excluded.minimum, duration_min=excluded.duration_min, source=excluded.source, condition=excluded.condition, homework=excluded.homework, repeatable_per=excluded.repeatable_per, tier=excluded.tier, sessao=excluded.sessao, porque=excluded.porque, blocos=excluded.blocos, min_bloco=excluded.min_bloco, tempo_fonte=excluded.tempo_fonte, ficha=excluded.ficha;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('E8',0,'modo','Modo do exercício','select',null,'{"options": ["Seleção de lista (50–100 atributos, escolher 5–7)", "Brainstorming livre (''se a marca fosse uma pessoa…'')", "Comparação binária (mais X ou mais Y?)"]}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('E8',1,'somos','A gente É','list',null,'{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('E8',2,'nao_somos','A gente NÃO é','list',null,'{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('E8',3,'selecionados','Atributos selecionados','list','5 a 7. Entram na prova real (E9). Refine em casa depois da imersão, buscando palavras melhores para a mesma ideia.','{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercises (id,phase_id,axis,name,intro,minimum,duration_min,source,condition,homework,repeatable_per,tier,sessao,porque,blocos,min_bloco,tempo_fonte,ficha) values ('E9','F3','E','Prova Real da Personalidade','Escolher atributo numa lista é fácil demais — "ah, a gente é honesto e transparente". Então tá bom, vamos ver. Seis atributos. Aqui você coloca o cliente contra ele mesmo.',true,10,'M05 A11',null,false,null,'espinha','workshop','Sem a prova real, atributo escolhido em lista é desejo, não diretriz. Vira o bloco 2 do relatório.',2,5,'padrão do método: 5 min por bloco',false) on conflict (id) do update set phase_id=excluded.phase_id, axis=excluded.axis, name=excluded.name, intro=excluded.intro, minimum=excluded.minimum, duration_min=excluded.duration_min, source=excluded.source, condition=excluded.condition, homework=excluded.homework, repeatable_per=excluded.repeatable_per, tier=excluded.tier, sessao=excluded.sessao, porque=excluded.porque, blocos=excluded.blocos, min_bloco=excluded.min_bloco, tempo_fonte=excluded.tempo_fonte, ficha=excluded.ficha;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('E9',0,'matriz','Por atributo','table',null,'{"columns": ["Atributo", "Ações que demonstram", "Práticas que comprovam", "Como os relacionamentos refletem", "Como a comunicação demonstra"], "repeatable": true, "max_rows": 6}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('E9',1,'lacunas','Onde a marca NÃO está exercendo','longtext','Vira conversa: querem exercer de verdade? Se querem, proponha ideias — ''se querem ser transparentes, dá para abrir as contas da empresa na internet''. É isso mesmo que vocês quiseram dizer?','{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercises (id,phase_id,axis,name,intro,minimum,duration_min,source,condition,homework,repeatable_per,tier,sessao,porque,blocos,min_bloco,tempo_fonte,ficha) values ('E10','F3','E','História da Marca (Donald Miller)','O herói nunca é a marca. O herói é o cliente; a marca é o guia. Serve para todo cliente — e vale treinar com marcas que você admira antes de aplicar.',false,35,'M05 A11',null,false,null,'sinal','workshop','A comunicação não tem narrativa: a marca se põe como herói em vez de guia.',7,5,'padrão do método: 5 min por bloco',false) on conflict (id) do update set phase_id=excluded.phase_id, axis=excluded.axis, name=excluded.name, intro=excluded.intro, minimum=excluded.minimum, duration_min=excluded.duration_min, source=excluded.source, condition=excluded.condition, homework=excluded.homework, repeatable_per=excluded.repeatable_per, tier=excluded.tier, sessao=excluded.sessao, porque=excluded.porque, blocos=excluded.blocos, min_bloco=excluded.min_bloco, tempo_fonte=excluded.tempo_fonte, ficha=excluded.ficha;
