insert into nave_exercises (id,phase_id,axis,name,intro,minimum,duration_min,source,condition,homework,repeatable_per,tier,sessao,porque,blocos,min_bloco,tempo_fonte,ficha) values ('VS1','F13','-','Conceitos Criativos e Moodboard','A ordem é fixa e a aula é explícita: estratégia → conceitos criativos → moodboards (se necessário) → Key Visual → identidade visual final. Só abra depois de estratégia, posicionamento, verbal e Key Word aprovados — "o designer que não entende de processo está tentando resolver o problema com 20% das informações". Durante o processo todo as ideias visuais aparecem: guarde num bloco de notas e NÃO execute antes da hora. AVISO DA AULA: moodboard não é piquenique. Não use para o cliente fazer o seu trabalho — ele não sabe o que quer, o especialista é você. Você apresenta num momento definido e pergunta o que ele acha; isso é diferente de ficar trocando figurinha o tempo todo e entregar o volante. E não suma: no máximo duas semanas entre uma validação e outra.',true,30,'M07 A14 (transcrição)',null,false,null,'fase','fase','',6,5,'padrão do método: 5 min por bloco',false) on conflict (id) do update set phase_id=excluded.phase_id, axis=excluded.axis, name=excluded.name, intro=excluded.intro, minimum=excluded.minimum, duration_min=excluded.duration_min, source=excluded.source, condition=excluded.condition, homework=excluded.homework, repeatable_per=excluded.repeatable_per, tier=excluded.tier, sessao=excluded.sessao, porque=excluded.porque, blocos=excluded.blocos, min_bloco=excluded.min_bloco, tempo_fonte=excluded.tempo_fonte, ficha=excluded.ficha;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('VS1',0,'tipo','Tipo de moodboard','select','Os dois tipos aparecem na aula. O primeiro testa território cedo; o segundo valida conceitos já formulados.','{"options": ["Teste de temperatura — várias opções de estilo/logo lado a lado, com os atributos ao lado, cliente comenta no Miro", "Painéis por conceito — um board por conceito criativo (ex.: sóbrio · colorido · divertido)", "Não vou usar moodboard neste projeto"]}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('VS1',1,'conceitos','Conceitos criativos (2 a 4)','table','São hipóteses e direções, não elementos. Ex.: resgatar o objeto renascentista que a fundadora ganhou da avó.','{"columns": ["Nome do conceito", "Justificativa estratégica", "Origem (história/personalidade/diferenciação/valores)", "Características visuais", "Aplicações possíveis"], "repeatable": true, "min_rows": 2, "max_rows": 4}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('VS1',2,'moodboards','Moodboards','table',null,'{"columns": ["Conceito", "Paleta e energia", "Referências tipográficas", "Estilo visual", "Aplicações sugeridas", "Link"], "repeatable": true}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('VS1',3,'argumento','Roteiro de apresentação antes de mostrar o board','longtext','Recapitule a estratégia inteira e as decisões do caminho ANTES de mostrar os painéis — "um projeto de marca é uma construção de argumentos para defender uma tese". Se você não construiu o argumento, o board não faz sentido nenhum.','{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('VS1',4,'reacao','Reação do cliente','longtext','Onde ele se sentiu proprietário? Onde ele se imagina habitando? O que gerou resistência? Se alguém pedir ''efeito uau'', é sinal de que não é profissional de verdade.','{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('VS1',5,'direcao','Direção de arte escolhida','longtext','É isto que entra no Key Visual (VS3).','{}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercises (id,phase_id,axis,name,intro,minimum,duration_min,source,condition,homework,repeatable_per,tier,sessao,porque,blocos,min_bloco,tempo_fonte,ficha) values ('VS2','F14','-','Sistema de Identidade (ativos de marca)','Ativos de marca, não checklist de logo/tipografia/cor. Um elemento vira ativo quando gera reconhecimento sozinho: cor, assinatura gráfica, símbolo, frase, expressão, som, nome, forma, gesto. A provocação da aula: "quando você tira o logo, o que resta é a identidade da marca". REGRA QUE MANDA EM TUDO: o sistema segue o cliente. A complexidade tem que partir da CAPACIDADE E DOS RECURSOS dele — não adianta entregar família de motion para quem não tem ninguém no social media. Se o cliente não sabe o que fazer com a entrega, a culpa é sua: entrega acadêmica copiada do guia do Google ou da Uber não serve. Ativo só é ativo se estiver sendo usado; se não é usado, não constrói valor.',true,35,'M07 A13 (transcrição)',null,false,null,'fase','fase','',7,5,'padrão do método: 5 min por bloco',false) on conflict (id) do update set phase_id=excluded.phase_id, axis=excluded.axis, name=excluded.name, intro=excluded.intro, minimum=excluded.minimum, duration_min=excluded.duration_min, source=excluded.source, condition=excluded.condition, homework=excluded.homework, repeatable_per=excluded.repeatable_per, tier=excluded.tier, sessao=excluded.sessao, porque=excluded.porque, blocos=excluded.blocos, min_bloco=excluded.min_bloco, tempo_fonte=excluded.tempo_fonte, ficha=excluded.ficha;
