insert into nave_exercise_fields (exercise_id,ord,key,label,type,hint,config) values ('VS2',6,'pontos_contato','Priorização de pontos de contato','table',null,'{"columns": ["Ponto de contato", "Prioridade (crítico/frequente/especial)"], "repeatable": true}'::jsonb) on conflict (exercise_id,key) do update set ord=excluded.ord, label=excluded.label, type=excluded.type, hint=excluded.hint, config=excluded.config;
insert into nave_exercises (id,phase_id,axis,name,intro,minimum,duration_min,source,condition,homework,repeatable_per,tier,sessao,porque,blocos,min_bloco,tempo_fonte,ficha) values ('VS3','F13','-','Key Visual (o cenário)','ATENÇÃO — o PDF define Key Visual como um elemento gráfico proprietário. A aula define outra coisa: o KV é o DOCUMENTO que apresenta a proposta de linguagem visual num estágio inicial, montando um cenário de como a marca vai se parecer funcionando. Formato Style Scape (Chris Do): antes eram 3 folhas A3 na horizontal impressas; hoje são 3 slides. "Não tem nada refinado. O logo não está certo, o kerning não está resolvido." É uma fachada — e é isso mesmo. Existe para o cliente conseguir dar feedback informado sem entrar no seu Figma, e para ancorar o projeto antes do refino: ir da estratégia direto para a identidade acabada "vai dar merda". Uma opção só — o moodboard é o que dispensa fazer duas. Prazo: uma semana ou menos.',true,50,'M07 A15 (transcrição — o PDF descreve outra coisa)',null,false,null,'fase','fase','',10,5,'padrão do método: 5 min por bloco',false) on conflict (id) do update set phase_id=excluded.phase_id, axis=excluded.axis, name=excluded.name, intro=excluded.intro, minimum=excluded.minimum, duration_min=excluded.duration_min, source=excluded.source, condition=excluded.condition, homework=excluded.homework, repeatable_per=excluded.repeatable_per, tier=excluded.tier, sessao=excluded.sessao, porque=excluded.porque, blocos=excluded.blocos, min_bloco=excluded.min_bloco, tempo_fonte=excluded.tempo_fonte, ficha=excluded.ficha;
